import numpy as np, torch, model
net=model.load()
rows=[2,5,6,7,11,12,14,15]
rng=np.random.default_rng(1); N=6000
c=rng.uniform(0,1,N).astype(np.float32); xi=rng.standard_normal((N,2)).astype(np.float32)
w=torch.tensor(np.load('contrast_c1_blocks.1.fc1_k16.npy')); b=-12.676
def dec(dv=None,thr=0.0,klo=0,khi=17):
    x=torch.tensor(xi); ct=torch.tensor(c); fired=torch.zeros(N,dtype=torch.bool); scs=[]
    with torch.no_grad():
        for k in range(20):
            t=torch.full((N,),1-k/20)
            v,acts=net.velocity(x,t,ct,capture=("blocks.1.fc1",))
            s=acts["blocks.1.fc1"]@w+b; scs.append(s)
            if dv is not None and klo<=k<khi:
                f=s>thr; fired|=f
                v=v+f[:,None].float()*torch.tensor(dv,dtype=torch.float32)
            x=x-v/20
    return x.numpy(),fired.numpy(),torch.stack(scs).numpy()
a0,_,sc=dec()
def badm(a):
    m=np.zeros(N,bool)
    for i in rows: m|=np.asarray(model.in_basin(i,a))
    return m
def othm(a):
    m=np.zeros(N,bool)
    for i in set(range(16))-set(rows): m|=np.asarray(model.in_basin(i,a))
    return m
lab=badm(a0)&(c<0.4); o0=othm(a0)
for k in [0,6,10,14]:
    for thr in [0,-4,-8]:
        f=sc[k]>thr; print('k',k,thr,round(f[lab].mean(),3),round(f[~lab].mean(),4))
res=[]
for thr in [-4,-8]:
  for (klo,khi) in [(6,17),(10,17)]:
    for ang in range(0,360,45):
      for mag in [2,4,8]:
        dv=[mag*np.cos(np.radians(ang)),mag*np.sin(np.radians(ang))]
        a,f,_=dec(-np.array(dv)*1.0,thr,klo,khi)  # v -= dir => x moves along dir
        bad=badm(a)&(c<0.4)
        moved=(np.linalg.norm(a-a0,axis=1)>0.2)
        r=(thr,klo,ang,mag,round(bad.sum()/max(lab.sum(),1),3),round(moved[~lab].mean(),4),round(othm(a).mean()-o0.mean(),4),round(f[~lab].mean(),4))
        res.append(r)
res.sort(key=lambda r:r[4]+3*r[5])
for r in res[:15]: print(r)

