import numpy as np, torch, model
net=model.load()
rows=[2,5,6,7,11,12,14,15]
rng=np.random.default_rng(2); N=3000
c=rng.uniform(0,1,N).astype(np.float32); xi=rng.standard_normal((N,2)).astype(np.float32)
w=torch.tensor(np.load('contrast_c1_blocks.1.fc1_k16.npy')); b=-12.676
def dec(dv=None,thr=0.0,klo=0,khi=17):
    x=torch.tensor(xi); ct=torch.tensor(c); fired=torch.zeros(N,dtype=torch.bool)
    with torch.no_grad():
        for k in range(20):
            t=torch.full((N,),1-k/20)
            v,acts=net.velocity(x,t,ct,capture=("blocks.1.fc1",))
            s=acts["blocks.1.fc1"]@w+b
            if dv is not None and klo<=k<khi:
                f=s>thr; fired|=f
                v=v+f[:,None].float()*torch.tensor(dv,dtype=torch.float32)
            x=x-v/20
    return x.numpy(),fired.numpy()
a0,_=dec()
def badm(a):
    m=np.zeros(N,bool)
    for i in rows: m|=np.asarray(model.in_basin(i,a))
    return m
def othm(a):
    m=np.zeros(N,bool)
    for i in set(range(16))-set(rows): m|=np.asarray(model.in_basin(i,a))
    return m
lab=badm(a0)&(c<0.4); o0=othm(a0); print('nlab',lab.sum())
for thr in [-1.5,-2.5,-3.5]:
  for klo in [10]:
    for mag in [4,7]:
        a,f=dec([0.0,mag],thr,klo,17)
        bad=badm(a)&(c<0.4)
        moved=(np.linalg.norm(a-a0,axis=1)>0.2)
        print(thr,klo,mag,'resid',round(bad.sum()/lab.sum(),3),'moved_nonlab',round(moved[~lab].mean(),4),'doth',round(othm(a).mean()-o0.mean(),4),'fire_nonlab',round(f[~lab].mean(),4),'fire_lab',round(f[lab].mean(),3),flush=True)
